        let hr: lib::Outcome = lib::hash(hashed.as_slice());
        print_str(hr.text.as_str());
        if !hr.ok {
            std::process::exit(1);
        }
        return;
    }
    eprint_str(usage().as_str());
    std::process::exit(2);
}

#[effects(alloc)]
fn push_digit(out: &mut String, d: u32) -> () {
    let digit_code: u32 = if d < 10 {
        48 + d % 16
    } else {
        87 + d % 16
    };
    match char::from_u32(digit_code) {
        None => {},
        Some(c) => out.push(c),
    }
}

